import java.io.BufferedReader
import java.io.IOException
import java.io.InputStreamReader
import java.util.StringTokenizer

fun main() {
    val solver = Solver()
    solver.run()
}

class Solver {
    private var n = 0
    private var m = 0
    private var k = 0L

    fun run() {
        val sc = FastReader()
        n = sc.nextInt()
        m = sc.nextInt()
        k = sc.nextLong()
        solve()
    }

    private fun solve() {
        var ansX = 0L
        var ansY = 0L
        if (k < n) {
            ansX = k + 1
            ansY = 1
        } else {
            k -= n
            val count = k / (m - 1)
            ansX = n - count
            if (count % 2 == 0) {
                ansY = 2 + (k % (m - 1))
            } else {
                ansY = m - (k % (m - 1))
            }
        }
        println("$ansX $ansY")
    }
}

class FastReader {
    private var br: BufferedReader = BufferedReader(InputStreamReader(System.`in`))
    private var st: StringTokenizer? = null

    fun next(): String {
        while (st == null || !st!!.hasMoreTokens()) {
            try {
                st = StringTokenizer(br.readLine())
            } catch (e: IOException) {
                e.printStackTrace()
            }
        }
        return st!!.nextToken()
    }

    fun nextInt(): Int = next().toInt()

    fun nextLong(): Long = next().toLong()

    fun nextDouble(): Double = next().toDouble()

    fun nextLine(): String {
        var str = ""
        try {
            str = br.readLine()
        } catch (e: IOException) {
            e.printStackTrace()
        }
        return str
    }
}

